"""scripts/dashboard_image_check.py (v3 slice 4, Verification V-IC): the pure parts. The checks themselves run inside the image
(CI's dashboard-image job, deploy.yml, make dashboard-image-check)."""

from __future__ import annotations

import ast
import sys

import pytest

from tests.scripts.stdlib_loader import ROOT, imported_modules, load_isolated

LOCK_EXCERPT = """#
# This file is autogenerated by pip-compile with Python 3.14
#
google-api-core[grpc]==2.42.0 \\
    --hash=sha256:aa
    # via google-cloud-bigquery
Streamlit==1.66.1 \\
    --hash=sha256:bb
    # via -r requirements-dashboard.in
watchdog==6.0.0 ; platform_system == "Linux" \\
    --hash=sha256:cc
    # via streamlit
typing_extensions==4.16.0 \\
    --hash=sha256:dd
"""


@pytest.fixture
def check(tmp_path):
    return load_isolated("dashboard_image_check", tmp_path)


def test_stdlib_only():
    assert imported_modules("dashboard_image_check") <= set(sys.stdlib_module_names) | {"__future__"}


def test_lock_pins_strips_extras_markers_and_canonicalizes(check):
    assert check.lock_pins(LOCK_EXCERPT) == {
        "google-api-core": "2.42.0", "streamlit": "1.66.1", "watchdog": "6.0.0", "typing-extensions": "4.16.0",
    }  # fmt: skip


def test_compare(check):
    pins = {"a": "1", "b": "2"}
    assert check.compare({"a": "1", "b": "2", "pip": "25.0"}, pins) == []
    assert check.compare({"a": "1"}, pins) == ["missing b==2"]
    assert check.compare({"a": "1", "b": "2", "c": "3"}, pins) == ["extra c==3"]
    assert check.compare({"a": "9", "b": "2"}, pins) == ["a: installed 9, pinned 1"]


def test_the_real_lockfile_parses_completely(check):
    text = (ROOT / "requirements-dashboard.txt").read_text()
    pin_lines = [line for line in text.split("\n") if line and not line[0].isspace() and not line.startswith("#")]
    assert len(check.lock_pins(text)) == len(pin_lines) > 40


def _lazy_google_imports() -> set[str]:
    """Modules the dashboard imports inside functions: dashboard/*.py, and gcp.py's credentials/bigquery_client."""
    found = set()
    sources = [*sorted((ROOT / "src" / "readmission_risk" / "dashboard").glob("*.py"))]
    for path in [*sources, ROOT / "src" / "readmission_risk" / "gcp.py"]:
        tree = ast.parse(path.read_text())
        functions = [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]
        if path.name == "gcp.py":
            functions = [f for f in functions if f.name in ("credentials", "bigquery_client")]
        for fn in functions:
            for node in ast.walk(fn):
                if isinstance(node, ast.Import):
                    found |= {a.name for a in node.names if a.name.startswith("google")}
                elif isinstance(node, ast.ImportFrom) and (node.module or "").startswith("google"):
                    found |= {f"{node.module}.{a.name}" if node.module in ("google.auth", "google.oauth2", "google.cloud", "google.api_core")
                              else node.module for a in node.names}  # fmt: skip
    return found


def test_lazy_imports_cover_every_function_level_google_import(check):
    assert _lazy_google_imports() <= set(check.LAZY_IMPORTS), _lazy_google_imports() - set(check.LAZY_IMPORTS)
    assert "google.cloud.storage" not in check.LAZY_IMPORTS  # not in the image: the dashboard never builds a storage client


def test_commit_ok(check):
    assert check.commit_ok("a" * 40, allow_missing=False) and check.commit_ok("a" * 40, allow_missing=True)
    assert not check.commit_ok("", allow_missing=False) and check.commit_ok("", allow_missing=True)
    assert not check.commit_ok("a" * 12, allow_missing=True)  # a short or malformed commit is never allowed


def test_main_refuses_unknown_arguments(check, capsys):
    assert check.main(["--bogus"]) == 2 and "usage" in capsys.readouterr().err
